    parseTrade(trade, market = undefined) {
        //
        // fetchTrades (public)
        //
        //      {
        //          "id": "206849494",
        //          "amount": "0.01",
        //          "rate": "5598346.0",
        //          "pair": "btc_jpy",
        //          "order_type": "sell",
        //          "created_at": "2021-12-08T14:10:33.000Z"
        //      }
        //
        // fetchMyTrades (private) - example from docs
        //
        //      {
        //          "id": 38,
        //          "order_id": 49,
        //          "created_at": "2015-11-18T07:02:21.000Z",
        //          "funds": {
        //              "btc": "0.1",
        //              "jpy": "-4096.135"
        //                  },
        //           "pair": "btc_jpy",
        //           "rate": "40900.0",
        //           "fee_currency": "JPY",
        //           "fee": "6.135",
        //           "liquidity": "T",
        //           "side": "buy"
        //      }
        //
        const timestamp = this.parse8601(this.safeString(trade, 'created_at'));
        const id = this.safeString(trade, 'id');
        const priceString = this.safeString(trade, 'rate');
        const marketId = this.safeString(trade, 'pair');
        const marketResolved = this.safeMarket(marketId, market, '_');
        const baseId = marketResolved['baseId'];
        const quoteId = marketResolved['quoteId'];
        const symbol = marketResolved['symbol'];
        let takerOrMaker = undefined;
        let amountString = undefined;
        let costString = undefined;
        let side = undefined;
        let fee = undefined;
        let orderId = undefined;
        if ('liquidity' in trade) {
            if (this.safeString(trade, 'liquidity') === 'T') {
                takerOrMaker = 'taker';
            } else if (this.safeString(trade, 'liquidity') === 'M') {
                takerOrMaker = 'maker';
            }
            const funds = this.safeDict(trade, 'funds', {});
            amountString = this.safeString(funds, baseId);
            costString = this.safeString(funds, quoteId);
            fee = {
                'currency': this.safeString(trade, 'fee_currency'),
                'cost': this.safeString(trade, 'fee')
            };
            side = this.safeString(trade, 'side');
            orderId = this.safeString(trade, 'order_id');
        } else {
            amountString = this.safeString(trade, 'amount');
            side = this.safeString(trade, 'order_type');
        }
        return this.safeTrade({
            'id': id,
            'info': trade,
            'datetime': this.iso8601(timestamp),
            'timestamp': timestamp,
            'symbol': symbol,
            'type': undefined,
            'side': side,
            'order': orderId,
            'takerOrMaker': takerOrMaker,
            'price': priceString,
            'amount': amountString,
            'cost': costString,
            'fee': fee
        }, marketResolved);
    }
