    parseTransactionStatusByType(status = undefined, type = undefined) {
        const statusesByType = {
            'deposit': {
                'New': 'pending',
                'AdminProcessing': 'pending',
                'Accepted': 'pending',
                'Rejected': 'rejected',
                'SystemProcessing': 'pending',
                'FullyProcessed': 'ok',
                'Failed': 'failed',
                'Pending': 'pending',
                'Confirmed': 'pending',
                'AmlProcessing': 'pending',
                'AmlAccepted': 'pending',
                'AmlRejected': 'rejected',
                'AmlFailed': 'failed',
                'LimitsAccepted': 'pending',
                'LimitsRejected': 'rejected'
            },
            'withdrawal': {
                'New': 'pending',
                'AdminProcessing': 'pending',
                'Accepted': 'pending',
                'Rejected': 'rejected',
                'SystemProcessing': 'pending',
                'FullyProcessed': 'ok',
                'Failed': 'failed',
                'Pending': 'pending',
                'Pending2Fa': 'pending',
                'AutoAccepted': 'pending',
                'Delayed': 'pending',
                'UserCanceled': 'canceled',
                'AdminCanceled': 'canceled',
                'AmlProcessing': 'pending',
                'AmlAccepted': 'pending',
                'AmlRejected': 'rejected',
                'AmlFailed': 'failed',
                'LimitsAccepted': 'pending',
                'LimitsRejected': 'rejected',
                'Submitted': 'pending',
                'Confirmed': 'pending',
                'ManuallyConfirmed': 'pending',
                'Confirmed2Fa': 'pending'
            }
        };
        const statuses = type === undefined ? {} : this.safeDict(statusesByType, type, {});
        if (status === undefined) {
            return undefined;
        }
        return this.safeString(statuses, status, status);
    }
